# 方法一：雙指標（推薦，單次查詢最佳）
class Solution:
    def isSubsequence(self, s: str, t: str) -> bool:
        i = 0
        for ch in t:
            if i < len(s) and s[i] == ch:
                i += 1
        return i == len(s)


# 方法二：預處理 + 二分（大量查詢用）
class Solution:
    def __init__(self):
        self.pos = None

    def isSubsequence(self, s: str, t: str) -> bool:
        import bisect
        from collections import defaultdict

        # 預處理：記錄每個字元出現的所有位置
        if self.pos is None:
            self.pos = defaultdict(list)
            for i, ch in enumerate(t):
                self.pos[ch].append(i)

        cur = -1
        for ch in s:
            lst = self.pos.get(ch)
            if not lst:
                return False
            # 找第一個 > cur 的位置
            idx = bisect.bisect_right(lst, cur)
            if idx == len(lst):
                return False
            cur = lst[idx]
        return True

