// 方法一：雙指標（推薦）
class Solution {
    public boolean isSubsequence(String s, String t) {
        int i = 0;
        for (int j = 0; j < t.length(); j++) {
            if (i < s.length() && s.charAt(i) == t.charAt(j)) {
                i++;
            }
        }
        return i == s.length();
    }
}

// 方法三：DP 狀態機
class Solution {
    public boolean isSubsequence(String s, String t) {
        int n = t.length();
        int[][] nxt = new int[n + 1][26];
        Arrays.fill(nxt[n], n);
        for (int i = n - 1; i >= 0; i--) {
            nxt[i] = nxt[i + 1].clone();
            nxt[i][t.charAt(i) - 'a'] = i;
        }

        int cur = 0;
        for (char c : s.toCharArray()) {
            if (nxt[cur][c - 'a'] == n) return false;
            cur = nxt[cur][c - 'a'] + 1;
        }
        return true;
    }
}

